package org.mcrf.client

object BsSitesPresentation {
    fun label(index:Int)=when(index){0->"Напрямую · сайт 1";1->"Напрямую · сайт 2";2->"Через VPN · сайт 3";else->error("Unknown site slot")}
    fun choices(current:String)=(listOf(current)+BsDetectionSites.presets).distinct()
    const val HELP="Сайты 1 и 2 — проверка обычного интернета без VPN. MCRF обращается к ним напрямую через Wi-Fi или мобильную сеть. Два сайта нужны, чтобы сбой одного сайта не принимался за ограничение всей сети. Если оба не отвечают, автоопределение может переключить подключение в БС; если хотя бы один снова отвечает — вернуть обычный VPN.\n\nСайт 3 — проверка через выбранный сервер VPN. Он помогает заметить, что прямой интернет ещё отвечает, но сайт через VPN уже недоступен. При таком результате автоопределение тоже может переключиться в БС. Эта дополнительная проверка выполняется при подключённом VPN, а не в режиме локального прокси и не при работе в БС.\n\nВыбирайте обычно доступные HTTPS-сайты: недоступный сайт может дать ложный сигнал. MCRF проверяет ответ, а не содержимое страницы; это признак доступности, не доказательство блокировки.\n\nСайты 1 и 2 также проверяются при открытии MCRF: результат помогает показать подходящий раздел, но не меняет текущее подключение. Периодическая проверка и автоматическое переключение VPN ↔ БС работают только при включённом автоопределении БС. Они не меняют DNS, маршруты или сайты проверки задержки серверов. Стрелка открывает готовый список, карандаш — ввод своего домена. После изменения нажмите «Сохранить сайты»."
}
